/*
 * atoms.h — Atom table for the Epilog inference engine.
 *
 * An atom is an immutable, interned string. Every unique spelling maps to
 * exactly one AtomId. Comparisons are therefore O(1) integer comparisons.
 *
 * JPL rules observed:
 *   - No dynamic allocation after atom_table_init().
 *   - All loops have a statically provable upper bound (ATOM_TABLE_CAPACITY).
 *   - No recursion.
 *   - No more than one level of pointer indirection in public API.
 *   - Every function documents its preconditions; callers must check returns.
 */

#ifndef EPILOG_ATOMS_H
#define EPILOG_ATOMS_H

#include <stddef.h>   /* size_t  */
#include <stdint.h>   /* uint32_t */

/* -------------------------------------------------------------------------
 * Compile-time limits (Rule 2: fixed upper bounds for all loops/tables).
 * ------------------------------------------------------------------------- */

#define ATOM_TABLE_CAPACITY  4096U   /* max distinct atoms     */
#define ATOM_MAX_LEN          255U   /* max chars, excl. NUL   */

/* -------------------------------------------------------------------------
 * Public types
 * ------------------------------------------------------------------------- */

/*
 * AtomId — opaque handle; ATOM_ID_INVALID signals absence / error.
 * Zero is intentionally reserved so zero-initialised structs are safe.
 */
typedef uint32_t AtomId;
#define ATOM_ID_INVALID  0U
#define ATOM_ID_MIN      1U

/* Internal storage for one interned atom. */
typedef struct {
    char     spelling[ATOM_MAX_LEN + 1U]; /* NUL-terminated              */
    uint32_t hash;                         /* pre-computed FNV-1a hash    */
    AtomId   id;                           /* == slot index + ATOM_ID_MIN */
} Atom;

/*
 * AtomTable — fixed-size, open-addressed hash table.
 * Allocate on the stack or as a module-level static; do NOT heap-alloc.
 */
typedef struct {
    Atom     slots[ATOM_TABLE_CAPACITY];
    uint32_t count;   /* number of interned atoms */
} AtomTable;

/* -------------------------------------------------------------------------
 * Public API
 * ------------------------------------------------------------------------- */

/*
 * atom_table_init — zero-initialise *t before first use.
 * Must be called exactly once before any other atom_* function.
 * Returns 0 on success, -1 if t is NULL.
 */
int atom_table_init(AtomTable *t);

/*
 * atom_intern — intern the NUL-terminated string *spelling.
 * If an atom with this spelling already exists, returns its id.
 * If the table is full or the spelling is too long, returns ATOM_ID_INVALID.
 * spelling must not be NULL.
 */
AtomId atom_intern(AtomTable *t, const char *spelling);

/*
 * atom_lookup — find an already-interned atom by spelling.
 * Returns ATOM_ID_INVALID if not found. Does not insert.
 */
AtomId atom_lookup(const AtomTable *t, const char *spelling);

/*
 * atom_spelling — return a pointer to the NUL-terminated spelling of id.
 * Returns NULL if id is out of range.
 * The pointer is valid for the lifetime of *t; do NOT free it.
 */
const char *atom_spelling(const AtomTable *t, AtomId id);

/*
 * atom_count — number of distinct atoms currently interned.
 */
uint32_t atom_count(const AtomTable *t);

#endif /* EPILOG_ATOMS_H */

/*
 * variables.h — Logic variable registry for the Epilog inference engine.
 *
 * A logic variable is an unbound or bound slot in a unification frame.
 * Variables are identified by a VarId scoped to a VarRegistry that lives
 * for the duration of a single query. The registry is reset between queries;
 * no heap allocation occurs after init.
 *
 * Binding is represented as a union-find structure without path compression
 * to keep pointer depth ≤ 1 and behaviour fully predictable (JPL rule 7).
 * Binding chains are therefore at most VAR_REGISTRY_CAPACITY long, which is
 * statically bounded (JPL rule 2).
 *
 * JPL rules observed:
 *   - No dynamic allocation after var_registry_init().
 *   - All loops have a statically provable upper bound.
 *   - No recursion — walk() is an explicit bounded loop.
 *   - No more than one level of pointer indirection in public API.
 *   - Every function checks its parameters; callers must check returns.
 */

#ifndef EPILOG_VARIABLES_H
#define EPILOG_VARIABLES_H

#include <stddef.h>    /* size_t   */
#include <stdint.h>    /* uint32_t */
#include "atoms.h"     /* AtomId   */

/* -------------------------------------------------------------------------
 * Compile-time limits
 * ------------------------------------------------------------------------- */

#define VAR_REGISTRY_CAPACITY  1024U  /* max variables per query frame */
#define VAR_NAME_MAX_LEN         63U  /* max chars in a variable name  */

/* -------------------------------------------------------------------------
 * Public types
 * ------------------------------------------------------------------------- */

/*
 * VarId — opaque handle. VAR_ID_INVALID signals absence / error.
 */
typedef uint32_t VarId;
#define VAR_ID_INVALID  0U
#define VAR_ID_MIN      1U

/*
 * TermTag — discriminates what a bound variable holds.
 */
typedef enum {
    TERM_UNBOUND = 0, /* variable is free          */
    TERM_ATOM,        /* bound to an interned atom  */
    TERM_VAR          /* bound to another variable  */
} TermTag;

/*
 * Binding — the value slot inside a VarEntry.
 * Union kept flat so pointer depth never exceeds 1.
 */
typedef union {
    AtomId atom_id; /* valid when tag == TERM_ATOM */
    VarId  var_id;  /* valid when tag == TERM_VAR  */
} BindingValue;

/*
 * VarEntry — one slot in the registry.
 */
typedef struct {
    char         name[VAR_NAME_MAX_LEN + 1U]; /* source-level name, may be "_" */
    TermTag      tag;
    BindingValue value;
    VarId        id; /* == slot index + VAR_ID_MIN */
} VarEntry;

/*
 * VarRegistry — fixed-size store for one query's variables.
 * Allocate as a local or static; do NOT heap-alloc.
 */
typedef struct {
    VarEntry entries[VAR_REGISTRY_CAPACITY];
    uint32_t count;
} VarRegistry;

/*
 * WalkResult — return type for var_walk.
 */
typedef struct {
    TermTag      tag;
    BindingValue value;    /* meaningful when tag != TERM_UNBOUND */
    VarId        root_id;  /* the canonical (deepest bound) VarId */
} WalkResult;

/* -------------------------------------------------------------------------
 * Public API
 * ------------------------------------------------------------------------- */

/*
 * var_registry_init — zero-initialise *r before first use.
 * Must be called once per query, before any other var_* function.
 * Returns 0 on success, -1 if r is NULL.
 */
int var_registry_init(VarRegistry *r);

/*
 * var_alloc — allocate a fresh unbound variable named *name.
 * name must be NUL-terminated and ≤ VAR_NAME_MAX_LEN chars.
 * Returns VAR_ID_INVALID if the registry is full or name is NULL.
 */
VarId var_alloc(VarRegistry *r, const char *name);

/*
 * var_bind_atom — bind variable id to atom atom_id.
 * Fails (returns -1) if id is already bound or either argument is invalid.
 * Returns 0 on success.
 */
int var_bind_atom(VarRegistry *r, VarId id, AtomId atom_id);

/*
 * var_bind_var — bind variable id to another variable other_id.
 * Fails (returns -1) if id is already bound or either id is invalid.
 * Returns 0 on success.
 */
int var_bind_var(VarRegistry *r, VarId id, VarId other_id);

/*
 * var_walk — follow binding chain from id to its canonical root.
 * Terminates in at most VAR_REGISTRY_CAPACITY steps (bounded loop, no
 * recursion). Returns a WalkResult describing the final state.
 * On invalid id, result.tag == TERM_UNBOUND and result.root_id == VAR_ID_INVALID.
 */
WalkResult var_walk(const VarRegistry *r, VarId id);

/*
 * var_reset — clear all bindings, keeping capacity intact.
 * Equivalent to re-running var_registry_init on an existing registry.
 * Returns 0 on success, -1 if r is NULL.
 */
int var_reset(VarRegistry *r);

/*
 * var_count — number of variables currently allocated in *r.
 */
uint32_t var_count(const VarRegistry *r);

#endif /* EPILOG_VARIABLES_H */
